#include <cstdint>
namespace ks{class SerialReceiveTask final{public:enum class Stage{Hold,Dispatch,AwaitQueue,CompareStatus,AdmitStatus,CompareData,AdmitData,Publish,Restore,Finish,Complete};Stage stage()const{return stage_;}uint8_t status()const{return status_;}uint8_t data()const{return data_;}bool awaiting()const{return stage_==Stage::AwaitQueue;}bool resumeChild(uint8_t status,uint8_t data){if(!awaiting())return false;status_=status;data_=data;stage_=Stage::CompareStatus;return true;}unsigned nextClocks()const{switch(stage_){case Stage::Hold:case Stage::Restore:return 11;case Stage::Dispatch:return 20;case Stage::Finish:return 17;case Stage::AwaitQueue:case Stage::Complete:return 0;default:return 3;}}unsigned advanceBefore(unsigned available){unsigned used=0;while(auto cost=nextClocks()){if(cost>available-used)break;switch(stage_){case Stage::Hold:stage_=Stage::Dispatch;break;case Stage::Dispatch:stage_=Stage::AwaitQueue;break;case Stage::CompareStatus:stage_=Stage::AdmitStatus;break;case Stage::AdmitStatus:stage_=status_==1?Stage::CompareData:Stage::Dispatch;break;case Stage::CompareData:stage_=Stage::AdmitData;break;case Stage::AdmitData:stage_=data_<0xf8?Stage::Publish:Stage::Dispatch;break;case Stage::Publish:stage_=Stage::Restore;break;case Stage::Restore:stage_=Stage::Finish;break;case Stage::Finish:stage_=Stage::Complete;break;default:break;}used+=cost;}return used;}private:Stage stage_=Stage::Hold;uint8_t status_=0,data_=0;};}
